import React, { useState, useEffect } from "react";
import classes from "./LIfeTimeModal.module.css";
import axios from "axios";
import * as Urls from "../../Urls";
import Box from "@mui/material/Box";
import Button from "@mui/material/Button";
import Typography from "@mui/material/Typography";
import Modal from "@mui/material/Modal";
import { IoMdClose } from "react-icons/io";
import { Dropdown } from "primereact/dropdown";

const style = {
  position: "absolute",
  top: "50%",
  left: "50%",
  transform: "translate(-50%, -50%)",
  bgcolor: "background.paper",
  border: "none",
  boxShadow: 24,
  borderRadius: "4px",
  p: 4,
};

const mobileStyle = {
  position: "absolute",
  bottom: 0,
  transition: "transform 0.3s ease-in-out",
  bgcolor: "background.paper",
  border: "none",
  boxShadow: 24,
  borderRadius: "4px",
  p: 2,
  overflow: "auto",
  maxHeight: "85%",
  width: "100%",
};
const successM = {
  position: "absolute",
  top: "50%",
  left: "50%",
  transform: "translate(-50%, -50%)",
  bgcolor: "background.paper",
  border: "none",
  boxShadow: 24,
  borderRadius: "4px",
  p: 4,
};

const AddBank = (props) => {
  const token = localStorage.getItem("swaToken");
  // const [successModalOpen, setSuccessModalOpen] = useState(false);
  const [open, setOpen] = useState(false);
  const [selectedCity, setSelectedCity] = useState(null);
  console.log(props.openSuccessModal);
  const [isMobileView, setIsMobileView] = useState(
    window.innerWidth >= 300 && window.innerWidth <= 575
  );
  const [bankDatas, setBankDatas] = useState({
    accountNo: "",
    reAccountNo: "",
    bankName: "Federal Bank",
    branch: "",
    ifsc: "",
    accountHolderName: "",
  });

  useEffect(() => {
    const handleResize = () => {
      setIsMobileView(window.innerWidth >= 300 && window.innerWidth <= 575);
    };

    window.addEventListener("resize", handleResize);

    // Cleanup function to remove event listener when component unmounts
    return () => {
      window.removeEventListener("resize", handleResize);
    };
  }, [isMobileView]);

  const handleOpen = () => {
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
  };

  const cities = [
    { name: "New York", code: "NY" },
    { name: "Rome", code: "RM" },
    { name: "London", code: "LDN" },
    { name: "Istanbul", code: "IST" },
    { name: "Paris", code: "PRS" },
  ];

  const addBank = async () => {
    try {
      const body = {
        account_number: bankDatas.accountNo,
        re_enter_account_number: bankDatas.reAccountNo,
        bank_name: bankDatas.bankName,
        branch: bankDatas.branch,
        ifsc: bankDatas.ifsc,
        account_holder_name: bankDatas.accountHolderName,
      };
      const response = await axios.post(Urls.addBankAccount, body, {
        headers: { Authorization: "Token " + token },
      });
      console.log("Bankresponse", response);
    } catch (error) {
      console.log(error);
    }
  };

  const handleChangeAddress = (event) => {
    const { name, value } = event.target;
    setBankDatas({
      ...bankDatas,
      [name]: value,
    });
  };

  return (
    <div>
      <Button onClick={handleOpen}>anas add bank account modal</Button>
      <Modal
        // open={props.open}
        open={open}
        // onClose={props.handleClose}
        onClose={handleClose}
      >
        <Box sx={isMobileView ? mobileStyle : style}>
          <Typography>
            <div className={classes.Container}>
              <div className={classes.LabelHead}>
                <p>Add bank A/C</p>
                <IoMdClose
                  style={{ cursor: "pointer" }}
                  // onClick={props.handleClose}
                  onClick={handleClose}
                />
              </div>
              <div className={classes.FormADDbANK}>
                <div className={classes.AccountLabels}>
                  <label>Enter Account Number</label>
                  <input
                    type="text"
                    placeholder="000153798763"
                    name="accountNo"
                    value={bankDatas.accountNo}
                    onChange={handleChangeAddress}
                  />
                </div>
                <div className={classes.AccountLabels}>
                  <label>Re Enter Account number</label>
                  <input
                    type="text"
                    placeholder="000153798763"
                    name="reAccountNo"
                    value={bankDatas.reAccountNo}
                    onChange={handleChangeAddress}
                  />
                </div>
                <div className={classes.AccountLabels}>
                  <label>Bank Name</label>
                  <Dropdown
                    value={selectedCity}
                    onChange={(e) => setSelectedCity(e.value)}
                    options={cities}
                    optionLabel="name"
                    placeholder="Axis bank"
                  />
                </div>
                <div className={classes.BranchIfscParent}>
                  <div className={classes.BranchAcc}>
                    <label>Branch</label>
                    <input
                      type="text"
                      placeholder="City*"
                      name="branch"
                      value={bankDatas.branch}
                      onChange={handleChangeAddress}
                    />
                  </div>
                  <div className={classes.BranchAcc}>
                    <label>IFSC</label>
                    <input
                      type="text"
                      placeholder="IFSC*"
                      name="ifsc"
                      value={bankDatas.ifsc}
                      onChange={handleChangeAddress}
                    />
                  </div>
                </div>
                <div className={classes.AccountLabels}>
                  <label>Account holder Name</label>
                  <input
                    type="text"
                    placeholder="Muhammed Jameel"
                    name="accountHolderName"
                    value={bankDatas.accountHolderName}
                    onChange={handleChangeAddress}
                  />
                </div>
                <div className={classes.AddBtnACC}>
                  <button onClick={addBank}>Add</button>
                </div>
              </div>
            </div>
          </Typography>
        </Box>
      </Modal>
    </div>
  );
};

export default AddBank;
